      var groups=existingGroups(rule,facts), shares=groups.length===1?[target]:split(target,groups.map(function(g){return g.weight;})), actual=0;
      groups.forEach(function(group,index){
        var capacities=group.members.map(function(f){return remaining[f.employeeId];});
        var available=capacities.reduce(function(a,b){return a+b;},0);
        var pieces=split(Math.min(shares[index],available),capacities);
        group.members.forEach(function(f,i){remaining[f.employeeId]-=pieces[i];totals[f.employeeId]+=pieces[i];actual+=pieces[i];});
      });
