      var due=demands[f.employeeId],amount=Math.min(due,capacity);
      if(due || entries.some(function(item){var e=item.entry;return (e.roles||e.role||e.employeeRoles||[]).indexOf(f.role)>=0||(e.employee||e.employees||[]).indexOf(f.name)>=0||(e.employee||e.employees||[]).indexOf(f.employeeId)>=0;}))contributions.push({employeeId:f.employeeId,name:f.name,role:f.role,before:f.originalTips,available:capacity/100,due:due/100,amount:amount/100,sources:{original:amount/100}});
