      var planned=sourceTargets?cents(sourceTargets[index]):cents(sourceBase(p,facts,dateKey)*rate/100),members=facts.filter(function(f){return f.role===cfg.role;}).sort(function(a,b){return String(a.employeeId).localeCompare(String(b.employeeId));});
