      var basis=members.map(function(f){var sales=sourceBase(p,[f],dateKey);return {sales:sales,value:sales};}),sum=basis.reduce(function(n,e){return n+e.value;},0);
      if(planned>0&&sum<=0)throw new Error('扣除方个人营业额合计为0，无法分摊');
