          if((cents(rule.plannedContribution)>0&&salesTotal<=0)||rule.employees.some(function(e){return !Number.isFinite(e.pct)||Math.abs(e.pct-(salesTotal?e.salesAmount/salesTotal*100:0))>1e-7;}))throw new Error('个人营业额占比不一致');
