          if((cents(rule.plannedContribution)>0&&totalBasis<=0)||rule.employees.some(function(e){return !Number.isFinite(e.pct)||Math.abs(e.pct-(totalBasis?e.allocationWeight/totalBasis*100:0))>1e-7;}))throw new Error('营业额加权占比不一致');
