    var list = Array.isArray(rules) ? rules : [];
    if (list.some(function(rule) { return String(rule && rule.id) === '5'; })) return list;
    var demoRule = defaultRules.find(function(rule) { return rule.id === 5; });
    if (!demoRule) return list;
