var dashboardAssetBase=window.tipoutDashboardAssetBase||'/tipout/dashboard/';
var dashboardReportKey='tipout-dashboard-report-v1';
function dashboardAssetUrl(name){return (window.tipoutDashboardAssets||{})[name]||dashboardAssetBase+name;}
function dashboardIcon(name){return '<img class="dashboard-icon" src="'+dashboardAssetUrl(name+'.svg')+'" alt="">';}
function isStoreSummaryRoute(){var p=new URLSearchParams(window.location.search);return p.get('screen')==='store'||p.get('view')==='employee';}
