function dashboardDateChange(){if(dashboardBusy)return;activeSummaryDatePreset='';document.getElementById('dateStart').value=document.getElementById('dashboardDateStart').value;document.getElementById('dateEnd').value=document.getElementById('dashboardDateEnd').value;if(!validateSummaryDateRange(false)){document.getElementById('dashboardDateError').textContent='请输入有效日期，开始日期不能晚于结束日期';return;}document.getElementById('dashboardDateError').textContent='';dashboardSyncDates();scheduleSummaryAutoAllocation();}
