      var workHoursConfig = normalizeWorkHoursConfig(rule.workHoursConfig);
      legacyTimeWindowHoursCap = rule.clockin === 'time_window' && rule.distribution === 'hours' && workHoursConfig.mode === 'capped';
      var legacyHoursAck = document.getElementById('legacyTimeWindowHoursAck');
      if (legacyHoursAck) legacyHoursAck.checked = false;
      var workHoursMode = document.querySelector('input[name="workHoursMode"][value="' + workHoursConfig.mode + '"]');
      if (workHoursMode) workHoursMode.checked = true;
