        document.querySelectorAll('#orderResidualReceiverTableBody tr.receiver-sub-row').forEach(function(tr) { updateReceiverRowWeightBtn(tr); });
        updateOrderResidualReceiverRoleOptions();
        document.querySelectorAll('#orderResidualReceiverTableBody .receiver-sub-tbody').forEach(function(tb) { updateSubReceiversRoleOptions(tb); });
        calcOrderResidualTotal();
