      document.querySelectorAll('#tipClaimsTableBody tr.tip-claim-row').forEach(function(tr) {
        if (tr === excludeRow) return;
        var ms = tr.querySelector('.tip-claim-role-select');
        if (!ms) return;
        ms.querySelectorAll('input[type="checkbox"]:checked').forEach(function(cb) {
          taken.push(cb.value);
        });
      });
